package ru.fifth.horror.block;
import net.minecraft.block.*;import net.minecraft.block.entity.BlockEntity;import net.minecraft.block.entity.BlockEntityTicker;import net.minecraft.block.entity.BlockEntityType;import net.minecraft.entity.player.PlayerEntity;import net.minecraft.item.ItemStack;import net.minecraft.text.Text;import net.minecraft.util.ActionResult;import net.minecraft.util.Hand;import net.minecraft.util.hit.BlockHitResult;import net.minecraft.util.math.BlockPos;import net.minecraft.world.World;import org.jetbrains.annotations.Nullable;import ru.fifth.horror.FifthMod;import ru.fifth.horror.item.VhsCassetteItem;
public final class CassetteDriveBlock extends BlockWithEntity{public CassetteDriveBlock(Settings s){super(s);}@Override public BlockEntity createBlockEntity(BlockPos pos,BlockState state){return new CassetteDriveBlockEntity(pos,state);}@Override public BlockRenderType getRenderType(BlockState state){return BlockRenderType.MODEL;}@Nullable @Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(World w,BlockState s,BlockEntityType<T> t){return w.isClient?checkType(t,FifthMod.CASSETTE_DRIVE_BE,CassetteDriveBlockEntity::tickClient):checkType(t,FifthMod.CASSETTE_DRIVE_BE,CassetteDriveBlockEntity::tick);}@Override public ActionResult onUse(BlockState state,World world,BlockPos pos,PlayerEntity p,Hand hand,BlockHitResult hit){BlockEntity be=world.getBlockEntity(pos);if(!(be instanceof CassetteDriveBlockEntity drive))return ActionResult.PASS;ItemStack held=p.getStackInHand(hand);if(held.isOf(FifthMod.VHS_CASSETTE)){if(!world.isClient){if(drive.hasCassette()){p.sendMessage(Text.literal("§7В кассетоводе уже есть кассета."),true);}else{ItemStack one=held.copy();one.setCount(1);drive.insert(one);if(!p.getAbilities().creativeMode)held.decrement(1);}}return ActionResult.success(world.isClient);}if(p.isSneaking()&&!world.isClient){ItemStack out=drive.ejectNow();if(!out.isEmpty())p.giveItemStack(out);return ActionResult.SUCCESS;}return ActionResult.PASS;}}
